insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('d-subject-recommendation-levels-measured-s700','decision','A Subjects recommendation takes the level its source measured on the titled codes','S700 (#3660, #3655): each title source is asked for every titled code with that code left out; High is 90% right or more, Medium 60%, Low below or under 20 asked; program titles cap at Medium; an agreeing source lifts one step, a differing one reads Low and both show, the title the code''s letters run through first. His to revise.',array['commons','subjects','recommendations'],'proposed','cpl-project-tracker#3660; kb/_build_local_subject_recommendations.py',null,null,'SkyGuillemot (S700)','2026-11-21'),
('f-subject-recommendations-measured-s700','fact','Subjects recommendations, measured 2026-11-21','S700, 1,331 titled codes: same code in the district, all agree 479 of 486; other colleges, all agree 229 of 232, one college 143 of 162; course joins, most agree 523 of 584; sibling one letter apart 44 of 62; program titles, several agree 99 of 157. 250 rows with no title: 109 High, 37 Medium, 60 Low, 44 none.',array['commons','subjects','recommendations'],'proposed','kb/status/local_subject_recommendations.json at cpl-project-tracker#3660',null,null,'SkyGuillemot (S700)','2026-11-21'),
('f-sams-30-cerritos-scored-s700','fact','The common-code recommender against Sam''s 30 Cerritos decisions: 22 agree, 6 diverge, 2 none','S700: the recommender (title, then own M-IDs, then the code statewide; the subject map unread) agrees on 22, has none for BCOT and WGS, and diverges on ASAM, AFRS, NAIS (Social Science; he chose ETHS, ETHA), ATH (KINE; he chose ATHL, not in the canonical file), AP (PHOT statewide; he chose BIOL), ACLR (IDST; he chose DSPS). His decision stands in each.',array['commons','subjects','cerritos','common-subj'],'proposed','kb/status/local_subject_recommendations.json common_code.sams_30; kb/reference/subject_code_decisions_cerritos_2026-11-21.json',null,null,'SkyGuillemot (S700)','2026-11-21'),
('f-missed-subject-pages-filed-s700','fact','The 21 index-linked subject pages are read and filed: 493 courses at four colleges','S700 (#3660): Cerritos 47, Long Beach City 47, Monterey Peninsula 71, Southwestern 328, parsed by kb/_file_missed_subject_pages.py from runs 44961387532 to 44962136733. No linked page is unread. Three pages print their courses under another code: Cerritos A&P prints AP, Monterey Peninsula SPCH prints COMM, Southwestern CBE prints ATCBE.',array['commons','subjects','catalogs','collection'],'proposed','kb/hand_filed_catalogs/courses/README.md; cpl-project-tracker#3660',null,null,'SkyGuillemot (S700)','2026-11-21'),
('d-local-title-drops-code-parenthetical-s700','decision','A local subject title drops the parenthetical that only repeats a subject code','S700 (#3660): 108 local titles read Biology (Biology) or History (Hist/History). The builder drops a parenthetical whose every part is a subject code of the college, or CCN; Basic Skills (Noncredit) stays. A heading that was only its code is no title (three rows now read Not read yet). Titled codes 1,334 to 1,331. His to revise.',array['commons','subjects','local-titles'],'proposed','kb/_build_local_subject_titles.py without_code; tests/local_subject_titles_test.py',null,null,'SkyGuillemot (S700)','2026-11-21'),
('p-read-plan-under-5000-lines-s700','pitfall','A page-read log reads back at most 5,000 lines, whatever tail_lines asks','S700: get_job_logs returned the last 5,000 lines of a 21-page read with tail_lines 20000, so 15 pages were read again in smaller plans. Size a plan by printed lines, not by plan count: a CourseLeaf subject page prints 250 to 400 lines, Southwestern ES/A 2,900. Push one plan per commit and wait for its run; a third queued run cancels the second.',array['collection','college-page-read','pitfall'],'proposed','kb/hand_filed_catalogs/courses/README.md; run 44961387532',null,null,'SkyGuillemot (S700)','2026-11-21')
on conflict (slug) do nothing;

insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('r-dept-labels-help-edge-recommendations-sam-2026-11-21','decision','A department or program label counts as evidence for a subject recommendation','Sam, 2026-11-21, in session (S700), on the web searches for Not in catalog rows, after Sky said it would leave out results that were program or department labels: "Dept labels can be helpful for our edge case recommendations". A label is kept and read as weaker evidence: it can agree or differ with another source, and by itself reads Low and says it is a label.',array['commons','subjects','recommendations','web-search'],'verified','Sam in session, 2026-11-21; kb/reference/subject_web_searches.json; kb/_build_local_subject_recommendations.py','Sam',now(),'SkyGuillemot (S700)','2026-11-21'),
('f-subject-web-searches-filed-s700','fact','108 web searches filed for the Not in catalog rows','S700, 2026-11-21: one search per Not in catalog row (4 by the session, 104 by two helpers). 61 found a subject title on the college''s own site, 8 of them on its catalog; 7 found a program or department label; 40 found nothing. With them the 250 rows with no title read 119 High, 20 Medium, 80 Low, 31 none (44 none before).',array['commons','subjects','recommendations','web-search'],'proposed','kb/reference/subject_web_searches.json; kb/status/local_subject_recommendations.json',null,null,'SkyGuillemot (S700)','2026-11-21')
on conflict (slug) do nothing;

-- Third statement: rows the session applied on 2026-11-22.
